    @pytest.mark.maintenance
    def test_fwUpgrade(self,getPositionByCol,getElementByPositionCol):
        self.driver.find_element(By.LINK_TEXT, "Maintenance").click()
        WebDriverWait(self.driver, 300).until(EC.visibility_of_element_located((By.LINK_TEXT, "Schedule")))
        self.driver.find_element(By.LINK_TEXT, "Schedule").click()
        self.driver.find_element(By.CSS_SELECTOR, "#i_action_create_collector > a").click()
        self.driver.find_element(By.ID, "schedule_type").click()
        Select(self.driver.find_element(By.ID, "schedule_type")).select_by_visible_text("Firmware upgrade")
        #self.driver.find_element(By.ID, "schedule_name").click()
        #self.driver.find_element(By.ID, "schedule_name").send_keys("AutoTest_FirmwareUpgrade")
        for cardType in range(len(dutAllCardID)):
            if dutAllCardID[cardType] == "0":
                continue
            self.driver.find_element(By.ID, "add_row").click()
            Select(self.driver.find_element(By.ID, "devtype")).select_by_visible_text(dutType)
            Select(self.driver.find_element(By.ID, "uploadTo")).select_by_visible_text(fwUploadName[cardType])
            self.driver.find_element(By.CSS_SELECTOR, ".maintenance_item:nth-child(1)").click()
            self.driver.find_element(By.ID, "load").send_keys(uploadPath + fwUploadFileName[cardType])
            self.driver.find_element(By.XPATH, "//label[contains(.,\'" + dutNodeName + "\')]").click()
            self.driver.find_element(By.CSS_SELECTOR, "#add_table .button").click()
        self.driver.find_element(By.ID, "time").click()
        scheduleTime = (datetime.now() + timedelta(seconds = 5)).strftime("%Y-%m-%d %H:%M:%S")
        self.driver.find_element(By.ID, "time").clear()
        self.driver.find_element(By.ID, "time").send_keys(scheduleTime)
        self.driver.find_element(By.CSS_SELECTOR, ".ui-datepicker-close").click()
        self.driver.find_element(By.ID, "timeout").click()
        self.driver.find_element(By.ID, "timeout").send_keys(Keys.CONTROL + "a")
        self.driver.find_element(By.ID, "timeout").send_keys(Keys.DELETE)
        self.driver.find_element(By.ID, "timeout").send_keys("180")
        self.driver.find_element(By.ID, "schedule_name").click()
        self.driver.find_element(By.ID, "schedule_name").clear()
        self.driver.find_element(By.ID, "schedule_name").send_keys("AutoTest_FirmwareUpgrade")
        self.driver.find_element(By.CSS_SELECTOR, ".button_center").click()
        time.sleep(300)
        self.driver.find_element(By.CSS_SELECTOR, "#i_action_refresh > a").click()
        entryPosition = getPositionByCol(self, "schedule_table", "ScheduleTime", scheduleTime)
        getElementByPositionCol(self, "schedule_table", entryPosition , "Result_Hyperlink").click()
        time.sleep(2)
        self.driver.find_element(By.CSS_SELECTOR, "#AddDevMagement .modal-content").screenshot("./report/FWupgradeDetail.png")
        self.driver.find_element(By.CSS_SELECTOR, "#AddDevMagement span").click()
        with assume:
            #Maintanence table summary assert
            assert getElementByPositionCol(self, "schedule_table", entryPosition , "ScheduleStatus").text == "Finish"
            assert getElementByPositionCol(self, "schedule_table", entryPosition , "Name").text == "AutoTest_FirmwareUpgrade"
            assert getElementByPositionCol(self, "schedule_table", entryPosition , "Type").text == "Firmware Upgrade"
            assert getElementByPositionCol(self, "schedule_table", entryPosition , "ScheduleType").text == "Once"
            assert getElementByPositionCol(self, "schedule_table", entryPosition , "Result_Hyperlink").text == "Success"
            assert getElementByPositionCol(self, "schedule_table", entryPosition , "Timeout").text == "180"
            #Maintanence table detail assert
            getElementByPositionCol(self, "schedule_table", entryPosition , "Modify").click()
            assert self.driver.find_element(By.ID, "schedule_type").get_attribute("value") == "maintenance/fw_upgrade"
            assert self.driver.find_element(By.ID, "schedule_name").get_attribute("value") == "AutoTest_FirmwareUpgrade"
            self.driver.find_element(By.CSS_SELECTOR, ".exit").click()

